template <typename K, typename V>
class LRUCache {
public:
    using key_type = K;
    using value_type = V;

    explicit LRUCache(std::size_t capacity)
        : capacity_(capacity) {
        assert(capacity_ > 0);
    }

    std::optional<V> get(const key_type& key) {
        auto it = map_.find(key);
        if (it == map_.end()) {
            return std::nullopt;
        }
        // Move the key to the front of the order vector (most recently used)
        map_[key] = std::move(it->second);
        order_.erase(it);
        order_.push_back(key);
        return map_[key];
    }

    void put(const key_type& key, const value_type& value) {
        auto it = map_.find(key);

        if (it != map_.end()) {
            // Update existing key
            map_[key] = std::move(it->second);
            order_.erase(it);
            order_.push_back(key);
        } else {
            // Insert new key
            if (order_.size() >= capacity_) {
                key_type evicted_key = order_.front();
                order_.pop_front();
                map_.erase(evicted_key);
            }
            map_[key] = std::move(value);
            order_.push_back(key);
        }
    }

    std::size_t size() const {
        return map_.size();
    }

private:
    struct Node {
        Node* prev;
        Node* next;
        Node(Node* prev, Node* next) : prev(prev), next(next) {}
    };

    std::size_t capacity_;
    std::size_t max_order_size_;

    std::unordered_map<key_type, V> map_;
    std::vector<Node> order_; // holds keys in usage order
    std::mutex mutex_;       // protect shared mutability
};
