from collections import defaultdict

def topo_sort(graph):
    # Identify all nodes: keys in graph and values in graph
    all_nodes = set(graph.keys())
    for prereq in graph.values():
        all_nodes.add(prereq)

    # Build reverse adjacency: dependent -> prerequisites
    reverse_adj = defaultdict(list)
    for node, prereqs in graph.items():
        for p in prereqs:
            reverse_adj[node].append(p)

    # Track visited status
    visited = {}
    order = []

    def dfs(node):
        if node in visited:
            return
        if visited.get(node) == 1:
            raise ValueError("Cycle detected")
        visited[node] = 1  # temporarily mark as being visited
        for prereq in sorted(reverse_adj.get(node, [])):
            dfs(prereq)
        visited[node] = 2
        order.append(node)

    for node in all_nodes:
        if node not in visited:
            dfs(node)

    return order
