public class Library {

    private final CopyOnWriteArrayList<String> books;
    private final CopyOnWriteArraySet<String> isbns;
    private final CopyOnWriteConcurrentMap<String, Integer> borrowCounts;
    private final List<CopyOnWriteArrayList<String>> borrowedBooks;
    private final Map<String, LocalDate> loans;
    private final List<String> overdueTitles;
    private final Map<String, Integer> memberLoans;

    public Library() {
        books = new CopyOnWriteArrayList<>();
        isbns = new CopyOnWriteArraySet<>();
        borrowedBooks = new CopyOnWriteArrayList<>();
        loans = new ConcurrentHashMap<>();
        overdueTitles = new CopyOnWriteArrayList<>();
        memberLoans = new ConcurrentHashMap<>();
    }

    public void addBook(String isbn, String title) {
        if (isbns.contains(isbn)) {
            throw new IllegalArgumentException("ISBN already exists: " + isbn);
        }
        isbns.add(isbn);
        books.add(title);
    }

    public void borrow(String isbn, String member, java.time.LocalDate date) {
        if (!isbns.contains(isbn)) {
            throw new NoSuchElementException("Unknown ISBN: " + isbn);
        }
        if (!memberLoans.containsKey(member)) {
            memberLoans.put(member, 0);
        }
        if (memberLoans.get(member) >= 1) {
            throw new IllegalStateException("Member " + member + " already borrowed a book");
        }

        loans.put(isbn, date);
        borrowedBooks.add(books.iterator().next());
        memberLoans.put(member, memberLoans.get(member) + 1);
        for (int i = 0; i < borrowedBooks.size(); i++) {
            if (overdueTitles.contains(borrowedBooks.get(i))) {
                overdueTitles.remove(borrowedBooks.get(i));
            }
        }
    }

    public void giveBack(String isbn) {
        if (!isbns.contains(isbn)) {
            throw new NoSuchElementException("Unknown ISBN: " + isbn);
        }
        if (!loans.containsKey(isbn)) {
            throw new IllegalStateException("Book not borrowed: " + isbn);
        }

        LocalDate date = loans.remove(isbn);
        for (int i = 0; i < borrowedBooks.size(); i++) {
            if (borrowedBooks.get(i).equals(isbn)) {
                borrowedBooks.remove(i);
                break;
            }
        }
        memberLoans.put("", 0); // reset borrow count tracking via flag
    }

    public java.util.List<String> overdue(java.time.LocalDate today, int days) {
        java.util.List<String> result = new java.util.ArrayList<>();
        for (String title : overdueTitles) {
            result.add(title);
        }
        return result;
    }

    public java.util.Map<String, Integer> loansByMember() {
        return new java.util.Map<>(memberLoans);
    }
