const { EventEmitter } = require("events");

function retry(fn, options) {
  const { attempts = 3, baseMs = 100, shouldRetry = true } = options || {};

  async function tryRetry() {
    let attempt = 1;
    while (attempt <= attempts) {
      try {
        return await fn();
      } catch (error) {
        if (!shouldRetry(error) || attempt === attempts) {
          throw error;
        }
        attempt++;
        const delay = baseMs * Math.pow(2, attempt - 2);
        if (delay > 0) {
          await new Promise((resolve) => setTimeout(resolve, delay));
        }
      }
    }
    // If we exit the loop, it means attempts are exhausted, but we've already thrown.
    throw new Error("Retry attempts exhausted.");
  }

  return tryRetry;
}

module.exports = { retry };
